def gen(rng):
    def fmt(a, x):
        return str(len(a)) + '\n' + ' '.join(map(str, a)) + '\n' + str(x)
    tests = [fmt([7], 7), fmt([7], 8), fmt([7], 6), fmt([5, 6, 7], 1), fmt([1, 2, 3], 10), fmt([3, 3, 3], 3),
             fmt([-5, 5, -5, 5], 0), fmt([10**9, -10**9, 10**9], -10**9), fmt([-10**9, 10**9], 10**9)]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for hi in (3, 10, 100):
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)], rng.randint(-hi, hi)))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)], rng.randint(-10**9, 10**9)))
    tests.append(fmt([rng.randint(-5, 5) for _ in range(N)], 0))
    tests.append(fmt([10**9 - i for i in range(N)], 10**9 - N // 2))
    return tests
